import torch,torch.nn as nn; exec("class MultiHeadedSelfAttention(nn.Module):\n    def __init__(self, embedding_dim, attention_dim, num_heads):\n        super().__init__()\n        torch.manual_seed(0)\n        self.att_heads = nn.ModuleList()\n        for i in range(num_heads):\n            self.att_heads.append(SingleHeadAttention(embedding_dim, attention_dim // num_heads))\n        self.output_proj = nn.Linear(attention_dim, attention_dim, bias=False)\n    def forward(self, embedded):\n        head_outputs = []\n        for head in self.att_heads:\n            head_outputs.append(head(embedded))\n        concatenated = torch.cat(head_outputs, dim=2)\n        return torch.round(self.output_proj(concatenated), decimals=4)\nclass SingleHeadAttention(nn.Module):\n    def __init__(self, embedding_dim, attention_dim):\n        super().__init__()\n        torch.manual_seed(0)\n        self.key_gen = nn.Linear(embedding_dim, attention_dim, bias=False)\n        self.query_gen = nn.Linear(embedding_dim, attention_dim, bias=False)\n        self.value_gen = nn.Linear(embedding_dim, attention_dim, bias=False)\n    def forward(self, embedded):\n        k = self.key_gen(embedded)\n        q = self.query_gen(embedded)\n        v = self.value_gen(embedded)\n        scores = q @ torch.transpose(k, 1, 2)\n        context_length, attention_dim = k.shape[1], k.shape[2]\n        scores = scores / (attention_dim ** 0.5)\n        lower_triangular = torch.tril(torch.ones(context_length, context_length))\n        mask = lower_triangular == 0\n        scores = scores.masked_fill(mask, float('-inf'))\n        scores = nn.functional.softmax(scores, dim=2)\n        return scores @ v")